from collections import deque
from itertools import product

def solve_pbe(pairs, max_ops=5):
    """Find replace operations transforming inputs to outputs via BFS."""
    def apply_replacement(s, a, b):
        return s.replace(a, b, 1)

    def check_program(program_ops):
        for inp, out in pairs:
            s = inp
            for a, b in program_ops:
                s = apply_replacement(s, a, b)
            if s != out:
                return False
        return True

    # Collect candidate a's and b's from input/output strings
    all_chars = set()
    for inp, out in pairs:
        for i in range(max_ops + 1):
            for j in range(i + 1, min(len(inp), 3) + 1):
                all_chars.add((inp[i:j], out))
            for i in range(max_ops + 1):
                for j in range(i + 1, min(len(out), 3) + 1):
                    all_chars.add((inp, out[i:j]))

    # Extract candidate substrings of length 1-3
    candidates_a = set()
    candidates_b = set()
    for inp, out in pairs:
        for length in range(1, 4):
            for i in range(len(inp)):
                if i + length <= len(inp):
                    candidates_a.add(inp[i:i+length])
        for length in range(0, 4):
            for i in range(len(out)):
                if i + length <= len(out):
                    candidates_b.add(out[i:i+length])

    # BFS over program sequences
    queue = deque()  # list of program_ops [(a1,b1), (a2,b2), ...]
    initial = []
    if check_program(initial):
        return ['']

    for a in candidates_a:
        for b in candidates_b:
            if (a, b) in initial:
                continue
            if a != b:
                queue.append([(a, b)])

    while queue:
        current = queue.popleft()
        if len(current) >= max_ops:
            continue
        for a in candidates_a:
            for b in candidates_b:
                if a != b:
                    new_ops = current + [(a, b)]
                    if check_program(new_ops):
                        return new_ops
                    queue.append(new_ops)

    return None

