from collections import deque

def solve_string_transform(pairs, max_ops=5):
    '''Find replace operations that transform input strings to output strings.

    Args:
        pairs: list of (input_string, output_string) tuples
        max_ops: maximum number of replace operations allowed
    Returns:
        list of formatted replace call strings
    '''
    # Collect all possible substrings of length 1-3 from inputs and outputs
    all_strings = set()
    for inp, out in pairs:
        all_strings.add(inp)
        all_strings.add(out)

    substrings_a = set()  # candidates for 'A' (the part to replace)
    substrings_b = set()  # candidates for 'B' (the replacement)

    for s in all_strings:
        for length in range(1, min(len(s), 3) + 1):
            for start in range(len(s) - length + 1):
                substrings_a.add(s[start:start+length])
        for length in range(0, min(len(s), 3) + 1):
            for start in range(len(s) - length + 1):
                substrings_b.add(s[start:start+length])

    # BFS over sequences of operations
    # State: tuple of current strings for all examples
    initial_state = tuple(p[0] for p in pairs)
    target_state = tuple(p[1] for p in pairs)

    if initial_state == target_state:
        return []

    queue = deque()
    queue.append((initial_state, []))  # (current_strings, operations)
    visited = set([initial_state])

    while queue:
        current_strings, ops = queue.popleft()

        if len(ops) >= max_ops:
            continue

        for a in sorted(substrings_a):
            for b in sorted(substrings_b):
                new_strings = tuple(s.replace(a, b) for s in current_strings)
                if new_strings not in visited:
                    visited.add(new_strings)
                    new_ops = ops + [(a, b)]
                    if new_strings == target_state:
                        return [f"replace('{a}', '{b}')" for a, b in new_ops]
                    queue.append((new_strings, new_ops))

    return []  # No solution found

