def solve_string_pbe(pairs, max_ops=5):
    '''Solves a Programming by Example string transformation by finding
    an ordered sequence of replace(A, B) operations via BFS search with pruning.

    Args:
        pairs: list of (input_string, output_string) tuples
        max_ops: maximum number of replace operations allowed

    Returns:
        list of (A, B) tuples forming the transformation sequence,
        or None if no solution found.
    '''
    from collections import deque
    from itertools import product

    all_inputs = [p[0] for p in pairs]
    all_outputs = [p[1] for p in pairs]

    def apply_ops(strings, ops):
        for a, b in ops:
            strings = [s.replace(a, b) for s in strings]
        return strings

    # Collect candidate A values: substrings from ALL input strings (len 1-3)
    candidate_as = set()
    for s in all_inputs:
        for i in range(len(s)):
            for j in range(i + 1, min(i + 4, len(s) + 1)):
                candidate_as.add(s[i:j])

    # Collect candidate B values: substrings from ALL output strings (len 0-3)
    candidate_bs = set([''])
    for s in all_outputs:
        for i in range(len(s)):
            for j in range(i, min(i + 4, len(s) + 1)):
                candidate_bs.add(s[i:j])

    # BFS: search for sequence of operations
    queue = deque()
    queue.append([])  # empty sequence

    while queue:
        ops = queue.popleft()
        transformed = apply_ops(list(all_inputs), ops)

        # Check if all examples match
        if transformed == list(all_outputs):
            return [(a, b) for a, b in ops]

        if len(ops) >= max_ops:
            continue

        # Find mismatched examples
        mismatched = [i for i in range(len(pairs)) if transformed[i] != all_outputs[i]]
        if not mismatched:
            continue

        # Prune: only try A values from mismatched strings
        next_as = set()
        for idx in mismatched:
            t = transformed[idx]
            for i in range(len(t)):
                for j in range(i + 1, min(i + 4, len(t) + 1)):
                    next_as.add(t[i:j])

        # Try all (A, B) combinations that reduce mismatches
        for a in next_as:
            for b in candidate_bs:
                # Quick simulation on mismatched strings only
                test_transformed = [transformed[i].replace(a, b) for i in mismatched]
                new_mismatch_count = sum(
                    1 for k, t in enumerate(test_transformed)
                    if t != all_outputs[mismatched[k]]
                )
                # Accept only if at least one mismatch improved
                if new_mismatch_count < len(mismatched):
                    queue.append(ops + [(a, b)])

    return None


def main():
    pairs = [
        ('wdf', 'wdf'),
        ('zcwick', 'zcwick'),
        ('wfgzaz', 'wfgzahz'),
        ('xf', 'xf'),
        ('hagcia', 'bvhgciah'),
    ]
    result = solve_string_pbe(pairs, max_ops=5)
    if result:
        print([f"replace('{a}', '{b}')" for a, b in result])
    else:
        print('No solution found')


if __name__ == '__main__':
    main()

