def solve_pbe_programs(pairs, max_ops=5):
    '''Finds an ordered sequence of replace(A,B) operations that transforms every
    input string into its paired output string. Uses BFS/DFS search with pruning.

    Args:
        pairs: List of (input_string, output_string) tuples
        max_ops: Maximum number of replace operations allowed

    Returns:
        List of 'replace(a, b)' call strings forming the program
    '''
    def apply_replace(s, a, b):
        return s.replace(a, b)

    def is_valid(program, pairs):
        for inp, out in pairs:
            result = inp
            for a, b in program:
                result = result.replace(a, b)
            if result != out:
                return False
        return True

    def generate_candidates():
        '''Generate possible (old, new) replacement pairs'''
        candidates = []
        # Collect all substrings of length 1-3 from input strings
        substrings = set()
        for inp, _ in pairs:
            for i in range(len(inp)):
                for j in range(i+1, min(i+4, len(inp)+1)):
                    substrings.add(inp[i:j])

        for old in substrings:
            for new_len in range(0, 4):
                # Generate new strings of length new_len using chars from existing strings
                all_chars = set()
                for inp, out in pairs:
                    all_chars.update(inp)
                    all_chars.update(out)
                if new_len == 0:
                    candidates.append((old, ''))
                else:
                    # Generate combinations with existing characters
                    from itertools import product
                    for combo in product(all_chars, repeat=new_len):
                        new = ''.join(combo)
                        if new != old:
                            candidates.append((old, new))
        return candidates

    import sys
    sys.setrecursionlimit(10000)

    candidates = generate_candidates()

    # DFS with iterative deepening
    def search(depth, program):
        if depth == max_ops:
            if is_valid(program, pairs):
                return program
            return None

        if is_valid(program, pairs):
            # Check if we can stop (all pairs already match)
            result = program
            all_match = True
            for inp, out in pairs:
                tmp = inp
                for a, b in result:
                    tmp = tmp.replace(a, b)
                if tmp != out:
                    all_match = False
                    break
            if all_match:
                return result

        for a, b in candidates:
            # Pruning: only add if it makes progress on at least one unmatched pair
            program.append((a, b))
            result = search(depth + 1, program)
            if result is not None:
                return result
            program.pop()

        return None

    result = search(0, [])
    if result is not None:
        return [f"replace('{a}', '{b}')" for a, b in result]
    return []

