from collections import deque


def solve_pbe_string(pairs, max_ops=5):
    """Solve a PBE string transformation problem by finding an ordered sequence
    of replace(A, B) operations via BFS search with pruning.

    Args:
        pairs: List of (input_str, output_str) tuples.
        max_ops: Maximum number of replace operations allowed.

    Returns:
        List of (a, b) tuples representing replace('a', 'b') operations,
        or None if no solution found within max_ops.
    """
    target = tuple(p[1] for p in pairs)
    initial = tuple(p[0] for p in pairs)

    if initial == target:
        return []

    # Gather candidate characters from all strings for building B values
    all_chars = set()
    for inp, out in pairs:
        all_chars.update(inp)
        all_chars.update(out)

    # Candidate B strings: empty string + all target substrings of length 1-3
    target_subs = set([''])
    for _, out in pairs:
        for i in range(len(out)):
            for j in range(i + 1, min(len(out) + 1, i + 4)):
                target_subs.add(out[i:j])

    def get_a_candidates(strings):
        """Get all substrings of length 1-3 from given strings."""
        cands = set()
        for s in strings:
            for i in range(len(s)):
                for j in range(i + 1, min(len(s) + 1, i + 4)):
                    cands.add(s[i:j])
        return cands

    # BFS over operation sequences
    queue = deque()
    queue.append((initial, []))
    visited = {initial}

    while queue:
        current, ops = queue.popleft()

        if len(ops) >= max_ops:
            continue

        a_candidates = get_a_candidates(current)

        for a in a_candidates:
            for b in target_subs:
                if a == b:
                    continue
                if len(b) > 3:
                    continue

                new_state = tuple(s.replace(a, b) for s in current)
                if new_state not in visited:
                    if new_state == target:
                        return ops + [(a, b)]
                    visited.add(new_state)
                    queue.append((new_state, ops + [(a, b)]))

    return None
